INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('b0a8-c758-b839', '{"clanId":"b0a8-c758-b839","personId":null,"nodes":[{"id":"K143","personId":"K143","kind":"person","name":"Nam Hwi-gang","birthDate":"2082-07-09","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K143"},{"path":"lore/characters/Cast-State-05.json","anchor":"Person-Nam-Hwigang-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Grew up at the Amsa guard post. The post of Floodgate Bridge Blockade Commander opened after catching a nighttime unauthorized river crossing.","sourceRefs":[{"path":"lore/characters/Cast-State-05.json","anchor":"Person-Nam-Hwigang-list2"}]}],"detailRoute":"/people/person-0144","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"K326","personId":"K326","kind":"person","name":"Nam Hoseong","birthDate":"2089-11-08","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K326"},{"path":"lore/characters/Cast-State-13.json","anchor":"person-nam-hoseong-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Raised at the Jegidong infirmary. The post of medical convoy specialist opened up because of a forged medicine seal.","sourceRefs":[{"path":"lore/characters/Cast-State-13.json","anchor":"person-nam-hoseong-list2"}]}],"detailRoute":"/people/person-0327","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K373","personId":"K373","kind":"person","name":"Nam Yun-gyeong","birthDate":"2091-05-02","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K373"},{"path":"lore/characters/Cast-State-15.json","anchor":"person-nam-yungyeong-p1"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Hand of the altar at Arc sanctuary, 74 Myeongdong-gil, Jung-gu. The Myeongdong altar and Arc registers were moved onto paper, and the Arc ratifies marriages and memorial rites at Myeongdong Station. Has a record of keeping the auction scales of the Seoul Station stockhouse clan unbroken. In the secret election of the Myeongdong Station congregation, Nam Yungyeong was elected Lead Believer, but the legitimacy of an election held without the Hierophant remains contested. The Arc''s jurisdiction stays with Myeongdong Station and the Arc sanctuary altar and Arc registers. The conference building on Gwangjin Myeonmok-ro is kept only as an outer storehouse. Ratification of marriage, adoption, and memorial rites continues after the election, but an objection that there is no ratification by the Hierophant follows every seal.","sourceRefs":[{"path":"lore/characters/Cast-State-15.json","anchor":"person-nam-yungyeong-p1"}]}],"detailRoute":"/people/person-0374","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K377","personId":"K377","kind":"person","name":"Nam Siyun","birthDate":"2080-02-16","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K377"},{"path":"lore/characters/Cast-State-15.json","anchor":"inmul-nam-siyun-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Raised on the waiting-hall watch. Served as the station election-affairs clerk at the Myeongdong Station office.","sourceRefs":[{"path":"lore/characters/Cast-State-15.json","anchor":"inmul-nam-siyun-list2"}]}],"detailRoute":"/people/person-0378","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K651","personId":"K651","kind":"person","name":"Nam Namwon","birthDate":"2085-10-08","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K651"},{"path":"lore/characters/Cast-State-04.json","anchor":"person-Nam-Namwon-list2"}],"timeline":[{"year":2126,"summary":"Born in the 2126 generation. Grew up at the Sinjeong rolling stock depot. The post of Parts Logistics Merchant opened af