INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('bc30-d765-d574-88f5', '{"clanId":"bc30-d765-d574-88f5","personId":null,"nodes":[{"id":"K110","personId":"K110","kind":"person","name":"Bae Na-gyeong","birthDate":"2072-02-06","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K110"},{"path":"lore/characters/Cast-State-04.json","anchor":"person-bae-nagyeong-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Grew up at the Yeongdeungpo Water Purification Watch. The post of Water Supply Contract Expiry Negotiation Clerk opened through the Valve Signature of Turbid Water Night.","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"person-bae-nagyeong-list2"}]}],"detailRoute":"/people/person-0111","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"K115","personId":"K115","kind":"person","name":"Bae Ujin","birthDate":"2083-03-04","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K115"},{"path":"lore/characters/Cast-State-05.json","anchor":"Person-Bae-Ujin-p1"}],"timeline":[{"year":2126,"summary":"Generation of 2126. A scion of the Arc warlord house. Mixing the civilian register with the guard register is taboo. It was not Bae Ujin''s forebears but the fact that the Amsa Arisu Water Purification Center remained within Seoul that tied eastern water purification and the Godeok base to military oversight. The commander''s seat is hereditary in the warlord house, and it opened only after the previous commander died and the chief of staff had served one year of emergency oversight. The blockade gate of the Changdong Bangho Clan belongs to I Hongwon. It was the hand of the Ministry of War that had Bae Ujin demand restoration-service registration in exchange for parts, and the house''s signature does not accompany it.","sourceRefs":[{"path":"lore/characters/Cast-State-05.json","anchor":"Person-Bae-Ujin-p1"}]}],"detailRoute":"/people/person-0116","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"FH-K110-P-01","personId":null,"kind":"historical","name":"Bae Seunghyeon","lineage":{"surname":"Bae","bongwan":"Heunghae","clan":"bc30-d765-d574-88f5"},"birthDate":"2042-02-06","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"person-bae-nagyeong-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2080,"summary":"Bae Seunghyeon compares household records with his child, who has been close to the work of cross-checking water supply contract copies at the Yeongdeungpo Water Purification Watch, and teaches the child to separate assigned duties from the family''s livelihood.","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"person-bae-nagyeong-list2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K110-P-02","personId":null,"kind":"historical","name":"Bae Seungyeong","lineage":{"surname":"Bae","bongwan":"Heunghae","clan":"bc30-d765-d574-88f5"},"birthDate":"2012-02-06","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"person-bae-nagyeong-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2030,"summary":"After the Great Blackout, Bae Seungyeong cross-checks goods names written in different dialects to reduce misunderstandings during exchanges.","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"person-bae-nagyeong-list2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K110-M-01","personId":null,"kind":"historical","name":"Choe Hyeonho","birthDate":"2042-02-06","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"person-bae-nagyeong-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2080,"summary":"Choe Hyeonho compares ho