INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('bc31-c218-c6d0', '{"clanId":"bc31-c218-c6d0","personId":null,"nodes":[{"id":"K245","personId":"K245","kind":"person","name":"Baek On","birthDate":"2102-10-04","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K245"},{"path":"lore/characters/Cast-State-10.json","anchor":"inmul-baek-on-p1"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Hand of the refugee register. Anguk Great Monastery is the head temple of the Janggyeong Order (hereafter ''Janggyeong''), and its capital is Anguk Station. Jogyesa and the General Affairs Office, 55 Ujeongguk-ro, Jongno-gu, kept the memorial tablets and temple ledgers after the Great Blackout. Baek On became abbot after the Mountain Assembly acclaimed him. The basis of the acclaim was that he kept the register chest of the Bukhansan Bogungmun Returnees'' Association unbroken. A lineage is a faction by master''s line, and the vote contests among the lineages are the politics of the Mountain Assembly. Anguk Great Monastery has no vassals and no army of its own. The Bukhansan refuge is a gap, not a household. Han Jaemok''s collective water cutoff turns the lines of the register into bargaining chips. This meets the reason Gang Minseo wants to raise citizenship together with the standard.","sourceRefs":[{"path":"lore/characters/Cast-State-10.json","anchor":"inmul-baek-on-p1"}]}],"detailRoute":"/people/person-0246","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K347","personId":"K347","kind":"person","name":"Baek Yeoul","birthDate":"2098-03-17","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K347"},{"path":"lore/characters/Cast-State-13.json","anchor":"person-baek-yeo-ul-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Grew up in the Jegidong infirmary. The apprentice herb-identification post opened through a counterfeit-medicine seizure.","sourceRefs":[{"path":"lore/characters/Cast-State-13.json","anchor":"person-baek-yeo-ul-list2"}]}],"detailRoute":"/people/person-0348","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K568","personId":"K568","kind":"person","name":"Baek Sanseok","birthDate":"2065-12-15","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K568"},{"path":"lore/characters/Cast-State-01.json","anchor":"inmul-baek-san-seok-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Grew up on the water-purification watch in Yeongdeungpo. The distribution district clerk post opened through a valve signature on the Night of Muddy Water.","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"inmul-baek-san-seok-list2"}]}],"detailRoute":"/people/person-0568","affiliation":{"kind":"state","stateId":"free-city","name":"Free City"}},{"id":"K955","personId":"K955","kind":"person","name":"Baek Arae","birthDate":"2076-12-08","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K955"},{"path":"lore/characters/Cast-State-04.json","anchor":"inmul-baek-arae-list2"}],"timeline":[{"year":2126,"summary":"Affiliation: Arc","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"inmul-baek-arae-list2"}]}],"detailRoute":"/people/person-0955","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"FH-K245-P-01","personId":null,"kind":"historical","name":"Baek Seungseok","lineage":{"surname":"Baek","bongwan":"Suwon","clan":"bc31-c218-c6d0"},"birthDate":"2072-10-04","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-10.json","anchor":"inmul-baek-on-p1"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2110,"summary":"Baek Seungseok, in the shared shelter of the living district, compares life records with a child who is close t