INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('bc94-ad6c-b85c-8303', '{"clanId":"bc94-ad6c-b85c-8303","personId":null,"nodes":[{"id":"FH-K1012-M-01","personId":null,"kind":"historical","name":"Nguyễn Thị Lan","nameEn":"Nguyễn Thị Lan","birthDate":"2059-04-17","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/name-pools/cast-family-trees.json","anchor":"FH-K1012-M-01"}],"timeline":[{"year":2077,"summary":"Nguyễn Thị Lan was born in 2059. She grew up reading the family records and work copies of the Guro Industrial Complex dormitory, and from 2077 she cross-checked goods handover details with her neighbors.","summaryEn":"Nguyễn Thị Lan was born in 2059 and grew up reading family and work records. From 2077, this ancestor compared goods-transfer records with neighbors.","sourceRefs":[{"path":"lore/name-pools/cast-family-trees.json","anchor":"FH-K1012-M-01"}]}],"detailRoute":null},{"id":"FH-K1012-M-02","personId":null,"kind":"historical","name":"Nguyễn Thị Hương","nameEn":"Nguyễn Thị Hương","birthDate":"2029-04-17","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/name-pools/cast-family-trees.json","anchor":"FH-K1012-M-02"}],"timeline":[{"year":2047,"summary":"Nguyễn Thị Hương was born in 2029. She grew up reading the family records and work copies of the Guro Industrial Complex dormitory, and from 2047 she cross-checked goods handover details with her neighbors.","summaryEn":"Nguyễn Thị Hương was born in 2029 and grew up reading family and work records. From 2047, this ancestor compared goods-transfer records with neighbors.","sourceRefs":[{"path":"lore/name-pools/cast-family-trees.json","anchor":"FH-K1012-M-02"}]}],"detailRoute":null},{"id":"FH-K1012-M-03","personId":null,"kind":"historical","name":"Trần Thị Mai","nameEn":"Trần Thị Mai","birthDate":"1999-04-17","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/name-pools/cast-family-trees.json","anchor":"FH-K1012-M-03"}],"timeline":[{"year":2030,"summary":"During the Great Blackout of around 2026, Trần Thị Mai worked as a skilled operator on the civilian night line of the Guro Industrial Complex, in the dormitory living district. After contact was lost, she wrote on paper the lodgings where her family would meet and the details of the goods handovers.","summaryEn":"Trần Thị Mai was in the family''s local community when communications failed around 2026. As a civilian, this ancestor recorded where the family could reunite and the transfer of household supplies.","sourceRefs":[{"path":"lore/name-pools/cast-family-trees.json","anchor":"FH-K1012-M-03"}]}],"detailRoute":null},{"id":"DF-PHAM-01","personId":null,"kind":"historical","name":"Phạm Văn Minh","birthDate":"1999-04-17","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/DF-PHAM-01"}],"timeline":[{"year":2030,"date":"2026","summary":"Around 2026 he kept manual maintenance going and guarded the dormitory shift roster on the Guro night line, and from 2046 he taught maintenance to his son Phạm Văn Tuấn.","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/DF-PHAM-01"}]},{"year":2046,"summary":"Around 2026 he kept manual maintenance going and guarded the dormitory shift roster on the Guro night line, and from 2046 he taught maintenance to his son Phạm Văn Tuấn.","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/DF-PHAM-01"}]}],"detailRoute":null},{"id":"DF-PHAM-02","personId":null,"kind":"historical","name":"Phạm Văn Tuấn","birthDate":"2029-04-17","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/DF-PHAM-02"}],"timeline":[{"year":2046,"summary":"He began learning maintenance in 2046, and in 2055 moved his residence to be near relatives in the Gasan living district, where he and his Guro colleagues divided up and kept copies of the maintenance records.","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/DF-PHAM-02"}]},{"year":2055,"summary":"He began learning maintenance in 2046, and in 2055 moved his residence to be near relatives in the Gasan living district, where he and his Guro colleagues divided up and kept copies of the maintenance records.","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/DF-PHAM-02"}]}],"detailRoute":null},{"id":"DF-PHAM-03","personId":null,"kind":"historical","name":"Phạm Văn Lộc","birthDate":"2059-04-17","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/DF-PHAM-03"}],"timeline":[{"year":2109,"summary":"In Gasan he taught maintenance records and the working language to his son Phạm Văn Đức, and in 2109 together they brought the family''s maintenance records to the Guro work site, checked them against the equipment, and learned repair.","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/DF-PHAM-03"}]}],"detailRoute":null},{"id":"K1012","personId":"K1012","kind":"person","name":"Pham Van Duc","birthDate":"2089-04-17","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/K1012"}],"timeline":[{"year":2109,"summary":"Phạm Văn Đức, born in the Gasan living district, brought the family''s maintenance records to the Guro work site in 2109 together with his father Phạm Văn Lộc, and learned barrier gate repair from the dormitory mechanics. By upholding tool returns and shift records he earned his colleagues'' trust and became night maintenance foreman. In 2126 he signs a food contract with Lin Xiaomei and negotiates the ammunition depot subcontract with Choe Ilseok. He uses his great-grandfather''s records as material explaining the work and the lodgings, and seeks to have the dormitory household roster recognized on a par with citizenship. A Vietnamese household remaining in the Guro Industrial Complex dormitory. His great-grandfather Phạm Văn Minh was a skilled night-line operator before the collapse. Phạm Văn Đức was born in the Gasan living district in 2089, and in 2109 together with his father Phạm Văn Lộc he brought the family''s maintenance records to the Guro work site and learned the work from the dormitory mechanics. He learned repair by checking old work records against the equipment, and by upholding tool returns and shift records he became night maintenance foreman. He speaks Vietnamese in daily conversation and uses Korean instructions at work. His great-grandfather Phạm Văn Minh, born in 1999, kept up manual maintenance with his colleagues when the Guro Industrial Complex equipment stopped around 2026. His son Phạm Văn Tuấn recorded the tools and their return details, and in 2055, when he moved his residence to be near relatives in the Gasan living district, he took copies with him and left one set in Guro as well. His grandson Phạm Văn Lộc deciphered and read those records in Gasan. In 2109 Phạm Văn Lộc brought the records with his son Phạm Văn Đức to the Guro work site and checked them against the equipment.","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/K1012"}]},{"year":2126,"summary":"Phạm Văn Đức, born in the Gasan living district, brought the family''s maintenance records to the Guro work site in 2109 together with his father Phạm Văn Lộc, and learned barrier gate repair from the dormitory mechanics. By upholding tool returns and shift records he earned his colleagues'' trust and became night maintenance foreman. In 2126 he signs a food contract with Lin Xiaomei and negotiates the ammunition depot subcontract with Choe Ilseok. He uses his great-grandfather''s records as material explaining the work and the lodgings, and seeks to have the dormitory household roster recognized on a par with citizenship. A Vietnamese household remaining in the Guro Industrial Complex dormitory. His great-grandfather Phạm Văn Minh was a skilled night-line operator before the collapse. Phạm Văn Đức was born in the Gasan living district in 2089, and in 2109 together with his father Phạm Văn Lộc he brought the family''s maintenance records to the Guro work site and learned the work from the dormitory mechanics. He learned repair by checking old work records against the equipment, and by upholding tool returns and shift records he became night maintenance foreman. He speaks Vietnamese in daily conversation and uses Korean instructions at work. His great-grandfather Phạm Văn Minh, born in 1999, kept up manual maintenance with his colleagues when the Guro Industrial Complex equipment stopped around 2026. His son Phạm Văn Tuấn recorded the tools and their return details, and in 2055, when he moved his residence to be near relatives in the Gasan living district, he took copies with him and left one set in Guro as well. His grandson Phạm Văn Lộc deciphered and read those records in Gasan. In 2109 Phạm Văn Lộc brought the records with his son Phạm Văn Đức to the Guro work site and checked them against the equipment.","sourceRefs":[{"path":"lore/name-pools/diaspora-family-lineages.json","anchor":"guro-pham-family/K1012"}]}],"detailRoute":"/people/person-1012","affiliation":{"kind":"state","stateId":"free-city","name":"Free City"}}],"edges":[{"id":"FH-K1012-M-02:FH-K1012-M-01:biological","from":"FH-K1012-M-02","to":"FH-K1012-M-01","type":"biological","parentRole":"mother","status":"authored","sourceRefs":[{"path":"lore/name-pools/cast-family-trees.json","anchor":"FH-K1012-M-02"}]},{"id":"FH-K1012-M-03:FH-K1012-M-02:biological","from":"FH-K1012-M-03","to":"FH-K1012-M-02","type":"biological","parentRole":"mother","status":"authored","sourceRefs":[{"path":"lore/name-pools/cast-family-trees.json","anchor":"FH-K1012-M-03"}]},{"id":"DF-PHAM-01:DF-PHAM-02