INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('c624-d574-c8fc', '{"clanId":"c624-d574-c8fc","personId":null,"nodes":[{"id":"K148","personId":"K148","kind":"person","name":"O Seo-yul","birthDate":"2067-11-29","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K148"},{"path":"lore/characters/Cast-State-06.json","anchor":"person-oseoyul-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Grew up at the Seoul Station Registry Office. The post of Contract Notary opened up through the deletion of a single line in a double ledger.","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"person-oseoyul-list2"}]}],"detailRoute":"/people/person-0149","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K194","personId":"K194","kind":"person","name":"Oh Hae-rin","birthDate":"2078-11-27","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K194"},{"path":"lore/characters/Cast-State-08.json","anchor":"inmul-Oh-Haerin-p1"}],"timeline":[{"year":2126,"summary":"Oh Haerin is the current AI avatar of the Government and uses Namsan Tower as her base. The intelligence service has operated as an independent, neutral organization since around 2026. The Government''s AI has continued to lead the organization, replacing only the avatar. The current avatar is Oh Haerin. Originally an intelligence organization, the Government preserves the internal Seoul records remaining in Namsan Tower and judges whether recovery is possible. Based on these records, the Government seeks to restore a legitimate organization. Generation of 2126. She worked in the archive of the Preservation Office in Heukseok-dong, Dongjak-gu. Only an occupation is listed. Oh Haerin directly holds Seoul Tower. The cold-storage key of the Frozen Merchant Company belongs to Gu Haon. Ice credit remains as neighbors'' debt. If Han Jaemok opens the prices, the warehouse is exposed; if he closes them, Yangcheon''s taps run dry first.","sourceRefs":[{"path":"lore/characters/Cast-State-08.json","anchor":"inmul-Oh-Haerin-p1"}]}],"detailRoute":"/people/person-0195","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K223","personId":"K223","kind":"person","name":"Oh Haneul","birthDate":"2081-08-02","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K223"},{"path":"lore/characters/Cast-State-09.json","anchor":"inmul-ohaneul-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Raised on waiting hall duty. The Investment Council Clerk post opened through a substitute shift covering an unexcused absence.","sourceRefs":[{"path":"lore/characters/Cast-State-09.json","anchor":"inmul-ohaneul-list2"}]}],"detailRoute":"/people/person-0224","affiliation":{"kind":"state","stateId":"free-city","name":"Free City"}},{"id":"K250","personId":"K250","kind":"person","name":"O Han-gyeol","birthDate":"2095-07-22","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K250"},{"path":"lore/characters/Cast-State-10.json","anchor":"person-ohangyeol-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Grew up on the Yeongdeungpo water-purification watch. The post of Ration Watch Abbot opened through a valve signature on Turbid Water Night.","sourceRefs":[{"path":"lore/characters/Cast-State-10.json","anchor":"person-ohangyeol-list2"}]}],"detailRoute":"/people/person-0251","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K423","personId":"K423","kind":"person","name":"O Gyeongjae","birthDate":"2104-08-22","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K423"},{"path":"lore/characters/Cast-State-04.json","anchor":"Character-O-Gyeongjae-p1"}],"timeline":[{"year":2126,"summary":"Generation of 2126. The last on-duty trainee at the General Assembly Hall, 29 Daehangno 3-gil, Jongno-gu. After Im Hajun disappeared in winter 2125, he took over the pump maintenance records between the Ttukseom heat source and the General Assembly in Yeonji-dong. Unlike Im Chowon, who learned pump maintenance, O Gyeongjae received the confirmation and took over the work of Im Hajun. The work has passed from father to son in the O clan, and the elders'' ratification vote remains a ritual. O Gyeongjae did not ratify Han Jaemok''s western expansion proposal. He agreed to jointly seal the original box of the pump maintenance process with the Free City.","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"Character-O-Gyeongjae-p1"}]}],"detailRoute":"/people/person-0088","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"K980","personId":"K980","kind":"person","name":"O Taho","birthDate":"2073-04-01","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K980"},{"path":"lore/characters/Cast-State-13.json","anchor":"character-otaho-list2"}],"timeline":[{"year":2126,"summary":"Livelihood: Quarantine Records and Duty Key Handover","sourceRefs":[{"path":"lore/characters/Cast-State-13.json","anchor":"character-otaho-list2"}]}],"detailRoute":"/people/person-0980","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"FH-K148-P-01","personId":null,"kind":"historical","name":"O Seungseong","lineage":{"surname":"O","bongwan":"Haeju","clan":"c624-d574-c8fc"},"birthDate":"2037-11-29","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"person-oseoyul-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2075,"summary":"O Seungseong checks living records against those of a child who has grown up close to the notarization of contract termination conditions and witness columns at the Seoul Station Registry Office, and teaches the child to separate their work from the family''s household affairs.","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"person-oseoyul-list2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K148-P-02","personId":null,"kind":"historical","name":"O Seunguk","lineage":{"surname":"O","bongwan":"Haeju","clan":"c624-d574-c8fc"},"birthDate":"2007-11-29","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"person-oseoyul-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2030,"summary":"O Seunguk sets the sleeping order in the communal shelter after the Great Blackout and divides up the remaining bedding.","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"person-oseoyul-list2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K148-M-01","personId":null,"kind":"historical","name":"Yun Seungmi","birthDate":"2037-11-29","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"person-oseoyul-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2075,"summary":"Yun Seungmi checks living records against those of a child who has grown up close to the notarization of contract termination conditions and witness columns at the Seoul Station Registry Office, and teaches the child to separate their work from the family''s household affairs.","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"person-oseoyul-list2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K148-M-02","personId":null,"kind":"historical","name":"Han Hyeonseok","birthDate":"2007-11-29","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"person-oseoyul-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"yea