INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('c724-d30c-d3c9', '{"clanId":"c724-d30c-d3c9","personId":null,"nodes":[{"id":"K144","personId":"K144","kind":"person","name":"Yun Seo-rin","birthDate":"2099-02-11","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K144"},{"path":"lore/characters/Cast-State-06.json","anchor":"inmul-yun-seorin-p1"}],"timeline":[{"year":2126,"summary":"Generation of 2126. The hand of the registered duty officer at the Government Complex Seoul main building, 209 Sejong-daero, Jongno-gu. Forging records is forbidden. Without the government seal, water-supply contracts in the city center have no force. Yun Seorin became president after keeping the seal case of the Bukhansan Bogukmun Recorder unbroken. The seal case of the Seoul Station Records Jurists belongs to Yeo Rian. In 2126 the government, from Cheongwadae, handled the residents'' registers, rations and ratifications for Jongno and Jung, and the Government Complex Seoul guard corps protected the downtown stations. If Han Jaemok''s western plan is halted, debts pile up; if it is stamped, Yangcheon''s veto dies.","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"inmul-yun-seorin-p1"}]}],"detailRoute":"/people/person-0145","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K147","personId":"K147","kind":"person","name":"Yun Ji-yul","birthDate":"2064-07-24","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K147"},{"path":"lore/characters/Cast-State-06.json","anchor":"inmul-yunjiyul-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Grew up at the Seoul Station Registry Office. The Medical Transport Recorder post opened through the deletion of a single line in a double ledger.","sourceRefs":[{"path":"lore/characters/Cast-State-06.json","anchor":"inmul-yunjiyul-list2"}]}],"detailRoute":"/people/person-