INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('c774-c804-c758-674e', '{"clanId":"c774-c804-c758-674e","personId":null,"nodes":[{"id":"K998","personId":"K998","kind":"person","name":"I Ilseop","birthDate":"2092-04-14","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K998"},{"path":"lore/characters/Cast-State-02.json","anchor":"person-lee-ilseop-p3"}],"timeline":[{"year":2126,"summary":"Life. Heir of the Lee clan that carries on the First Sub-Workshop. In 2121, in his workshop duties at Oryu 2-dong, he tilled the field and managed the grain stock. The field and storage space were used for this work and were neither the clan''s territory nor its exclusive property. In 2123, before submitting the winter ration plan, he recounted the grain stock three times, and proposed to the Free City Council that part of the sub-workshop''s parts payments be accepted in seed.","sourceRefs":[{"path":"lore/characters/Cast-State-02.json","anchor":"person-lee-ilseop-p3"}]}],"detailRoute":"/people/person-0998","affiliation":{"kind":"state","stateId":"geography:duchy:11620","name":"Gwanak-gu"}},{"id":"FH-EX-LEE-SANGGYE","personId":null,"kind":"historical","name":"Lee Sanggye","lineage":{"surname":"I","bongwan":"Jeonui","clan":"c774-c804-c758-674e"},"birthDate":"2062-04-14","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/name-pools/cast-hangnyeol.json"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2092,"summary":"Lee Sanggye hands life records to his children and passes on the family name.","sourceRefs":[{"path":"lore/characters/Cast-State-02.json","anchor":"person-lee-ilseop-p3"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-EX-LEE-HOGYE","personId":null,"kind":"historical","name":"Lee Hogye","lineage":{"surname":"I","bongwan":"Jeonui","clan":"c774-c804-c758-674e"},"birthDate":"2032-04-14","deathDate":null,"status":"authored","sourceRefs":[{"