INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('c784-c870-c591-6797', '{"clanId":"c784-c870-c591-6797","personId":null,"nodes":[{"id":"K036","personId":"K036","kind":"person","name":"Im Chaewon","birthDate":"2096-11-16","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K036"},{"path":"lore/characters/Cast-State-02.json","anchor":"person-im-chaewon-list2"}],"timeline":[{"year":2126,"summary":"Born in the generation of 2126. Raised on waiting-hall duty. The post of Protective Suit Trade Representative opened through a substitute duty shift covering an unexcused absence.","sourceRefs":[{"path":"lore/characters/Cast-State-02.json","anchor":"person-im-chaewon-list2"}]}],"detailRoute":"/people/person-0036","affiliation":{"kind":"state","stateId":"free-city","name":"Free City"}},{"id":"K086","personId":"K086","kind":"person","name":"Im Hajun","birthDate":"2072-12-03","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K086"},{"path":"lore/characters/Core-Characters.json","anchor":"Im-Hajun-p2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. In 2119, O Gyeongjae, the legitimate eldest son of the O clan, was a minor. The members opened a confirmation vote and entrusted that work to Im Hajun. The hands that had learned pump specifications on duty at the Ttukseom heat source passed only half of that skill on to his adopted son Im Chowon. In the winter of 2125, Im Hajun disappeared. The night before his disappearance, he sealed the copy box of the pump-cleaning process. The key to the sealed box was received by the General Assembly together with the three-page will. Bak Nuri served as interim custodian. The circumstances of the disappearance and the contents of the three-page will have not been determined.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Im-Hajun-p2"}]}],"detailRoute":"/people/person-0086","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"K087","personId":"K087","kind":"person","name":"Im Chowon","birthDate":"2100-06-11","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K087"},{"path":"lore/characters/Core-Characters.json","anchor":"Im-Chowon-p2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Grew up beside the pumps. What was learned from Im Hajun was not succession to the Council but pump maintenance technology. Rank: Teacher. On the shift after the disappearance in the winter of 2125, he confirmed the seal on the original box. The confirmed fact was entered in the witness column of the three-page will. In 2126, O Gyeongjae received the confirmation and took over the work of Im Hajun. Im Chowon remains a pump technician at the opening.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Im-Chowon-p2"}]}],"generationException":{"reason":"Preserve the confirmed birth date and the existing Im Hajun→Im Chowon relationship. Do not change the relationship or the dates to fit the 30-year gap.","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json"},{"path":"lore/characters/Core-Characters.json","anchor":"/content/40"}]},"detailRoute":"/people/person-0087","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"K089","personId":"K089","kind":"person","name":"Bak Serin","birthDate":"2093-07-25","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K089"},{"path":"lore/characters/Cast-State-04.json","anchor":"Person-Bak-Serin-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Raised at the Sinjeong rail depot. The post of Acting Head of the Pump-Technology Family opened after a defect report filed just before a derailment.","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"Person-Bak-Serin-list2"}]}],"detailRoute":"/people/person-0090","affiliation":{"kind":"state","st