INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('c815-c9c4-c591-912d', '{"clanId":"c815-c9c4-c591-912d","personId":null,"nodes":[{"id":"K398","personId":"K398","kind":"person","name":"Jeong Yura","birthDate":"2090-01-26","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K398"},{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Yura-p2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Contract auditor at the former Gyeonghyang Shinmun building site, 3 Jeongdong-gil, Jung-gu. Forging records is forbidden. The union membership roster in the Jeongdong office became an emergency muster. When the factories stopped, the right to strike turned into the right of passage. Jeong Yura became chairwoman only after she kept the Suseo Builder House''s standard protective blueprints from being cut off. Suseo Depot remains ownerless, unclaimed land. The Sicheong Station General Federation acts as though it were a state. When three powers simultaneously presented the weaker states with different water-supply contracts, Jeong Yura put termination conditions and audit rights onto a single sheet. That sheet became the backbone of the negotiations. Jang Sehwa''s convoy carries that sheet. She is a member of the Jeong branch family. She is a distant relative of Jeong Seoon.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Yura-p2"}]}],"detailRoute":"/people/person-0399","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"K1005","personId":"K1005","kind":"person","name":"Jeong Seoon","birthDate":"2090-06-17","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K1005"},{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p2"}],"timeline":[{"year":2126,"summary":"Life. Generation of 2126. She is the only daughter of Jeong Ilhwan. She is entered in the clan genealogy without a generation-name character. The argument for a male heir in the branch family continued. The Orthodox Society gave no answer to the succession approval. That silence remained a burden within the family. Jeong Yura is a member of the Jeong branch family. She is a distant relative of Jeong Seoon.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p2"}]}],"detailRoute":"/people/person-1005","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"FH-EX-JEONG-ILHWAN","personId":null,"kind":"historical","name":"Jeong Ilhwan","lineage":{"surname":"Jeong","bongwan":"Jinyang","clan":"c815-c9c4-c591-912d"},"birthDate":"2060-06-17","deathDate":"2112-04-09","status":"authored","sourceRefs":[{"path":"lore/chronology/Century-Annals.json"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2112,"summary":"Jeong Ilhwan dies amid the conflict over succession approval in the family, leaving behind his only daughter, Jeong Seoon.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K1005-M-01","personId":null,"kind":"historical","name":"Song Minjae","birthDate":"2060-06-17","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2098,"summary":"In the communal dwelling of the living quarter, when a new family moves into the dwelling, Song Minjae mends and hands over unused bedding and rearranges the household with her child.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K1005-M-02","personId":null,"kind":"historical","name":"Jo Mindo","birthDate":"2030-06-17","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2068,"summary":"In the communal dwelling of the living quarter, when words got crossed while sharing supplies with another household, Jo Mindo records debts and exchanged goods separately and teaches his child the habit of cross-checking.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K1005-M-03","personId":null,"kind":"historical","name":"Kim Minon","birthDate":"2000-06-17","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2030,"summary":"When everyday communication was cut off by the Great Blackout, Kim Minon records the family''s dwellings and well-being to track down news of scattered relatives.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K1005-XJeongIlhwan-01","personId":null,"kind":"historical","name":"Jeong Seoyeong","lineage":{"surname":"Jeong","bongwan":"Jinyang","clan":"c815-c9c4-c591-912d"},"birthDate":"2030-06-17","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2068,"summary":"In the communal dwelling of the living quarter, when she came to share a dwelling with an unfamiliar neighbor, Jeong Seoyeong listened to their way of living and rewrote the family''s promises.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K1005-XJeongIlhwan-02","personId":null,"kind":"historical","name":"Jeong Seoyun","lineage"