INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('c815-c9c4-c8fc-912d', '{"clanId":"c815-c9c4-c8fc-912d","personId":null,"nodes":[{"id":"K006","personId":"K006","kind":"person","name":"Jeong Mo-ran","birthDate":"2070-05-14","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K006"},{"path":"lore/characters/Cast-State-01.json","anchor":"person-jeong-moran-list2"}],"timeline":[{"year":2126,"summary":"Born in the 2126 generation. Grew up at the Noryangjin wharf. The post of Yeouido Waterborne Transport Guild Master opened through the public disclosure of a scale recheck.","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"person-jeong-moran-list2"}]}],"detailRoute":"/people/person-0006","affiliation":{"kind":"state","stateId":"free-city","name":"Free City"}},{"id":"K057","personId":"K057","kind":"person","name":"Jeong Hojun","birthDate":"2101-05-14","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K057"},{"path":"lore/characters/Cast-State-03.json","anchor":"Person-Jeong-Hojun-p1"}],"timeline":[{"year":2126,"summary":"Born in the 2126 generation. A hand on the field test line at the Yangjae headquarters, 12 Heolleung-ro, Seocho-gu. Around 2026 that yard was already running humanoids, and when cloud learning died, the maintenance family kept the trade name. Forgery of records is forbidden. The Jeong chairman family inherits the chairmanship, and the chairman at the opening is Jeong Seoon. When a proposal to bind researchers to a hereditary trade in the name of protection came before the family council, Jeong Hojun moved the samples into the communal property column and struck out the hostage clause. The chairmanship opened not through that deletion but through family succession. It reads as the same habit as Jeong Yura''s termination condition. If Gang Minseo locks the standard, the Yangjae ledger cannot keep up. With the Magok Saengmyeong Clan''s inspection key left in Magok''s ownerless land, they dispute the scope of disclosure.","sourceRefs":[{"path":"lore/characters/Cast-State-03.json","anchor":"Person-Jeong-Hojun-p1"}]}],"detailRoute":"/people/person-0057","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"K398","personId":"K398","kind":"person","name":"Jeong Yura","birthDate":"2090-01-26","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K398"},{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Yura-p2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Contract auditor at the former Gyeonghyang Shinmun building site, 3 Jeongdong-gil, Jung-gu. Forging records is forbidden. The union membership roster in the Jeongdong office became an emergency muster. When the factories stopped, the right to strike turned into the right of passage. Jeong Yura became chairwoman only after she kept the Suseo Builder House''s standard protective blueprints from being cut off. Suseo Depot remains ownerless, unclaimed land. The Sicheong Station General Federation acts as though it were a state. When three powers simultaneously presented the weaker states with different water-supply contracts, Jeong Yura put termination conditions and audit rights onto a single sheet. That sheet became the backbone of the negotiations. Jang Sehwa''s convoy carries that sheet. She is a member of the Jeong branch family. She is a distant relative of Jeong Seoon.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Yura-p2"}]}],"detailRoute":"/people/person-0399","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"K1005","personId":"K1005","kind":"person","name":"Jeong Seoon","birthDate":"2090-06-17","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K1005"},{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p2"}],"timeline":[{"year":2126,"summary":"Life. Generation of 2126. She is the only daughter of Jeong Ilhwan. She is entered in the clan genealogy without a generation-name character. The argument for a male heir in the branch family continued. The Orthodox Society gave no answer to the succession approval. That silence remained a burden within the family. Jeong Yura is a member of the Jeong branch family. She is a distant relative of Jeong Seoon.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p2"}]}],"detailRoute":"/people/person-1005","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"FH-EX-JEONG-ILHWAN","personId":null,"kind":"historical","name":"Jeong Ilhwan","lineage":{"surname":"Jeong","bongwan":"Jinyang","clan":"c815-c9c4-c591-912d"},"birthDate":"2060-06-17","deathDate":"2112-04-09","status":"authored","sourceRefs":[{"path":"lore/chronology/Century-Annals.json"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2112,"summary":"Jeong Ilhwan dies amid the conflict over succession approval in the family, leaving behind his only daughter, Jeong Seoon.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Jeong-Seoon-p1"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K006-P-01","personId":null,"kind":"historical","name":"Jeong Seungho","lineage":{"surname":"Jeong","bongwan":"Jinju","clan":"c815-c9c4-c8fc-912d"},"birthDate":"2040-05-14","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"person-jeong-moran-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2078,"summary":"When a neighbor who cannot read comes to him at the Noryangjin wharf, Jeong Seungho reads the household records aloud and has his children confirm what the records mean as well.","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"person-jeong-moran-list2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K006-P-02","personId":null,"kind":"historical","name":"Jeong Seungmin","lineage":{"surname":"Jeong","bongwan":"Jinju","clan":"c815-c9c4-c8fc-912d"},"birthDate":"2010-05-14","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"person-jeong-moran-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2030,"summary":"When the Great Blackout cut off everyday contact, Jeong Seungmin records where his family members are staying and whether they are safe, searching for news of his scattered relatives.","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"person-jeong-moran-list2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K006-M-01","personId":null,"kind":"historical","name":"Gang Seungho","birthDate":"2040-05-14","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"person-jeong-moran-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2078,"summary":"When words got crossed while sharing goods with another household at the Noryangjin wharf, Gang Seungho wrote down debts and exchanged goods separately and taught his children the habit of cross-checking.","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"person-jeong-moran-list2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K006-M-02","personId":null,"kind":"historical","name":"Im Seungjun","birthDate":"2010-05-14","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"person-jeong-moran-list2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2030,"summary":"When the Great Blackout cut off everyday contact, Im Seungjun records where his family members are staying and whether they are safe, searching for news of his scattered relati