INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('cd5c-acbd-c8fc', '{"clanId":"cd5c-acbd-c8fc","personId":null,"nodes":[{"id":"K219","personId":"K219","kind":"person","name":"Choe Ji-u","birthDate":"2099-01-28","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K219"},{"path":"lore/characters/Cast-State-09.json","anchor":"Character-Choe-Jiu-p1"}],"timeline":[{"year":2126,"summary":"Generation of 2126. The hand of the transmission watch at the Yeouido Hall, Yeoui-daero 24. The hall''s emergency committee converted the affiliated investment ledgers into a cooling-and-key watch. Choe Jiu became chair after keeping the transmission watch of the Magok Seed House and its investment ledgers from being cut off. The watch of the Digital Media City Trust House belongs to Choe Eunjae. False bulletins are cut first not by the Board of Punishments but by the Channel Guild. The Free City is a pharmacy. This society holds the common currency and the Yeouido vault, and cross-checks Seoul''s internal exchange and investment-ledger work against the Yeongdeungpo handover desk. If the voice is faster than Yun Seorin''s seal, the endorsement becomes a copy.","sourceRefs":[{"path":"lore/characters/Cast-State-09.json","anchor":"Character-Choe-Jiu-p1"}]}],"detailRoute":"/people/person-0220","affiliation":{"kind":"state","stateId":"free-city","name":"Free City"}},{"id":"K859","personId":"K859","kind":"person","name":"Choe Baa","birthDate":"2093-04-25","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K859"},{"path":"lore/characters/Cast-State-04.json","anchor":"inmul-Choe-Baa-list2"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Grew up at the Amsa guard post. The Yuchiseon Patrol post opened through catching an unauthorized night river crossing.","sourceRefs":[{"path":"lore/characters/Cast-State-04.json","anchor":"inmul-Choe-Baa-list2"}]}],"detailRoute":"/people/person-0859","affiliation":{"kind":"state","stateId":"arc","name":"Arc"}},{"id":"FH-K219-P-01","personId":null,"kind":"historical","name":"Choe Hyeonuk","lineage":{"surname":"Choe","bongwan":"Gyeongju","clan":"cd5c-acbd-c8fc"},"birthDate":"2069-01-28","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-09.json","anchor":"Character-Choe-Jiu-p1"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2107,"summary":"Choe Hyeonuk, in a communal dwelling in the living district, cross-checks living records with a child who has been close to living-supplies management work, and teaches the child to distinguish assigned work from the family''s household.","sourceRefs":[{"path":"lore/characters/Cast-State-09.json","anchor":"Character-Choe-Jiu-p1"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K219-P-02","personId":null,"kind":"historical","name":"Choe Hyeonran","lineage":{"surname":"Choe","bongwan":"Gyeongju","clan":"cd5c-acbd-c8fc"},"birthDate":"2039-01-28","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-09.json","anchor":"Character-Choe-Jiu-p1"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2077,"summary":"Choe Hyeonran, after living through days when rations ran late in a communal dwelling in the living district, first counts the food to set aside and so sustains the livelihood of the next generation.","sourceRefs":[{"path":"lore/characters/Cast-State-09.json","anchor":"Character-Choe-Jiu-p1"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K219-P-03","personId":null,"kind":"historical","name":"Choe Hyeonri","lineage":{"surname":"Choe","bongwan":"Gyeongju","clan":"cd5c-acbd-c8fc"},"birthDate":"2009-01-28","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Cast-State-09.json","anchor":"Character-Choe-Jiu-p1"},{"path":"lore/name-pools/cast-family-trees.json"}]