INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('d55c-ccad-c8fc', '{"clanId":"d55c-ccad-c8fc","personId":null,"nodes":[{"id":"K001","personId":"K001","kind":"person","name":"Han Jae-mok","birthDate":"2069-06-17","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K001"},{"path":"lore/characters/Cast-State-01.json","anchor":"Person-Han-Jaemok-p1"}],"timeline":[{"year":2126,"summary":"Generation of 2126. Raised in the care of the duty staff at the Seoul Arisu Headquarters'' Yeongdeungpo Arisu Water Purification Center. What the grandfather left behind was not a company name but a sluice key and a duty roster. With that key, Han Jaemok learned the habit of never opening the sluice before receiving the countersignatures of the ration district representatives. The water-contract houses chose a sovereign at the Yangpyeong Station contract assembly, and Han Jaemok gathered the votes of the Sluice House in that election and took the sovereign''s seat. The Yeouido Financial Hall split off as a neighboring state, and I Seodam''s installation as Yangcheon district head was a deal to preserve that countersignature as an institution.","sourceRefs":[{"path":"lore/characters/Cast-State-01.json","anchor":"Person-Han-Jaemok-p1"}]}],"detailRoute":"/people/person-0001","affiliation":{"kind":"state","stateId":"free-city","name":"Free City"}},{"id":"K037","personId":"K037","kind":"person","name":"Han Jion","birthDate":"2093-01-23","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K037"},{"path":"lore/characters/Cast-State-02.json","anchor":"inmul-hanjion-list2"}],"timeline":[{"year":2126,"summary":"Born in the 2126 generation. Grew up on waiting hall duty. The post of Geumcheon Raw Water and Food Citizen Representative opened through a substitute duty shift after an unexcused absence from rotation.","sourceRefs":[{"path":"lore/characters/Cast-State-02.json","anchor"