INSERT INTO family_tree (clan_id, json, json_ko) VALUES ('goryeong-shin', '{"clanId":"goryeong-shin","personId":null,"nodes":[{"id":"K1009","personId":"K1009","kind":"person","name":"Sin Jong-mok","birthDate":"2087-09-18","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K1009"},{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"}],"timeline":[{"year":2126,"summary":"Life. In November 2119, Sin Jongmok, a senior field agent of the Eastern Directorate Special Recovery Team, returned with refugees who were not on the roster. The team''s report recorded insubordination and loss of issued supplies, and listed some team members who had held the retreat route as missing. In April 2120, Sin Jongmok withdrew from the Special Recovery Team and moved with his son Sin Jun to the Gangnam-gu Office living area. He took escort and survey contracts and transmitted his old call sign over a repaired radio. In January 2121, he recorded responses from a medical station, residents, and guardians. By 2124, the return network linked twelve living areas from the Gangnam-gu Office to Seonjeongneung and Suseo.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"}]}],"detailRoute":"/people/person-1009","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"K1010","personId":"K1010","kind":"person","name":"Sin Jun","birthDate":"2114-01-01","deathDate":null,"status":"preserved","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json","anchor":"K1010"},{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jun-p2"}],"timeline":[{"year":2126,"summary":"Life. Sin Jun is Sin Jongmok''s son. In April 2120, he moved with his father to the Gangnam-gu Office living area. When abandoned-station broadcasts, radio noise, and vehicle vibration overlap, he recalls fragments of old call rhythms and routes. Sin Jongmok checks those reactions against field records and confirms Sin Jun''s consent and rest.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jun-p2"}]}],"generationException":{"reason":"Preserve the confirmed birth dates and the existing Sin Jongmok→Sin Jun relationship. Do not change the relationship or the dates to fit a 30-year gap.","sourceRefs":[{"path":"lore/name-pools/cast-birthdays.json"},{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jun-p2"}]},"detailRoute":"/people/person-1010","affiliation":{"kind":"state","stateId":"government","name":"The Government"}},{"id":"FH-K1009-P-01","personId":null,"kind":"historical","name":"Sin Hyeonyeong","lineage":{"surname":"Sin","bongwan":"Elderly","clan":"goryeong-shin"},"birthDate":"2057-09-18","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2095,"summary":"After losing items while carrying supplies in the living area''s shared dwelling, Sin Hyeonyeong reads out the list before tying up the load and confirms what each family member is carrying.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K1009-P-02","personId":null,"kind":"historical","name":"Sin Hyeonyun","lineage":{"surname":"Sin","bongwan":"Elderly","clan":"goryeong-shin"},"birthDate":"2027-09-18","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2065,"summary":"Because she had to move dwellings often in the living area''s shared dwelling, Sin Hyeonyun writes down sleeping places and food shares separately so her children can keep house even in unfamiliar places.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K1009-P-03","personId":null,"kind":"historical","name":"Sin Hyeonu","lineage":{"surname":"Sin","bongwan":"Elderly","clan":"goryeong-shin"},"birthDate":"1997-09-18","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2030,"summary":"After the Great Blackout cuts off everyday contact, Sin Hyeonu records his family''s lodgings and well-being to search for news of relatives who have scattered.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K1009-M-01","personId":null,"kind":"historical","name":"I Seosu","birthDate":"2057-09-18","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2095,"summary":"After living through days when rations ran late in the living area''s shared dwelling, I Seosu first counts the food to set aside, sustaining the next generation''s livelihood.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"},{"path":"lore/name-pools/cast-family-trees.json"}]}],"detailRoute":null},{"id":"FH-K1009-M-02","personId":null,"kind":"historical","name":"Choe Seohui","birthDate":"2027-09-18","deathDate":null,"status":"authored","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anchor":"Sin Jongmok-p2"},{"path":"lore/name-pools/cast-family-trees.json"}],"timeline":[{"year":2065,"summary":"When she comes to share a dwelling with unfamiliar neighbors in the living area''s shared dwelling, Choe Seohui listens to each one''s way of living and rewrites her family''s agreements.","sourceRefs":[{"path":"lore/characters/Core-Characters.json","anch